/* =========================================================================
 * Callback Types
 * ========================================================================= */

/**
 * @brief Legacy raw-data callback (for backward compatibility)
 */
typedef void (*dataflow_wifi_rx_callback_t)(const uint8_t* data, size_t len);

/**
 * @brief Protocol-aware frame callback
 *
 * Called when a valid protocol frame is received (with parsed header).
 * @param frame_id   Numeric frame identifier
 * @param frame_type df_frame_type_t value
 * @param sequence   Frame sequence number
 * @param payload    Pointer to payload data (after header), may be NULL for control frames
 * @param payload_len Length of payload in bytes (0 for control frames)
 */
typedef void (*dataflow_wifi_frame_callback_t)(uint16_t frame_id, uint8_t frame_type,
                                                uint16_t sequence,
                                                const uint8_t* payload, size_t payload_len);

/* =========================================================================
 * Public API — Initialization & Status
 * ========================================================================= */

esp_err_t dataflow_wifi_init(void);
esp_err_t dataflow_wifi_deinit(void);
bool dataflow_wifi_is_connected(void);

/* =========================================================================
 * Callback Registration
 * ========================================================================= */

/**
 * @brief Set legacy raw-data callback (used by old-style rx handlers)
 * @note  If a protocol frame callback is also set, protocol frames go to
 *        the frame callback and only legacy-format messages go here.
 */
void dataflow_wifi_set_rx_callback(dataflow_wifi_rx_callback_t callback);

/**
 * @brief Set protocol-aware frame callback
 * @note  When set, incoming messages with a valid df_wire_header are dispatched
 *        here. Legacy-format messages still go to the raw rx callback.
 */
void dataflow_wifi_set_frame_callback(dataflow_wifi_frame_callback_t callback);

/* =========================================================================
 * Sending — Legacy & Protocol-Aware
 * ========================================================================= */

/**
 * @brief Send raw bytes (legacy API, backward compatible)
 */
esp_err_t dataflow_wifi_send(const uint8_t* data, size_t len);

/**
 * @brief Send a protocol frame with header + payload
 *
 * Prepends a df_wire_header_t (5 bytes) before the payload and sends
 * the combined message via the length-prefixed transport.
 *
 * @param frame_id    Numeric frame ID from frame_descriptors.h
 * @param frame_type  df_frame_type_t (DATA, ACK, START_STREAM, etc.)
 * @param payload     Payload bytes (variable fields packed per descriptor), may be NULL
 * @param payload_len Payload length in bytes, 0 for control-only frames
 * @return ESP_OK on success
 */
esp_err_t dataflow_wifi_send_frame(uint16_t frame_id, uint8_t frame_type,
                                    const uint8_t* payload, size_t payload_len);

/**
 * @brief Send a control frame (header only, no payload)
 *
 * Convenience wrapper for START_STREAM, STOP_STREAM, ACK, NACK, HEARTBEAT.
 *
 * @param frame_id    Numeric frame ID
 * @param frame_type  df_frame_type_t (typically ACK, NACK, START_STREAM, STOP_STREAM)
 * @return ESP_OK on success
 */
esp_err_t dataflow_wifi_send_control(uint16_t frame_id, uint8_t frame_type);

/* =========================================================================
 * Connection Quality Metrics
 * ========================================================================= */

typedef struct {
    uint32_t packets_sent;
    uint32_t packets_received;
    uint32_t send_errors;
    uint32_t recv_errors;
    uint32_t reconnect_count;
    uint32_t unknown_frame_ids;
    uint32_t last_seen_ms;
    uint32_t protocol_frames_sent;
    uint32_t protocol_frames_received;
    uint32_t legacy_frames_received;
} dataflow_wifi_stats_t;

void dataflow_wifi_get_stats(dataflow_wifi_stats_t *stats);

